// Unlimited practice generated by Claude (page capability "sample"). Items use the same formats as grammar2.js.
const THEMES=['technology and society','the environment','education and universities','health and lifestyle','economy and business','culture and traditions','media and news','travel and tourism','work and careers','science and research','cities and housing','family and relationships'];
function needAI(out){
  if(AI)return false;
  out.innerHTML='<div class="warn">Эта функция работает, когда страница открыта внутри Claude (приложение или claude.ai). Здесь она недоступна.</div>';
  return true;
}
function validItem(q){
  if(!Array.isArray(q)||!q.every(x=>typeof x==='string'&&x.trim()))return false;
  const t=q[0],L=q.length;
  if(t==='m')return L===7&&new Set(q.slice(2,6).map(x=>x.toLowerCase())).size===4&&q[1].includes('___');
  if(t==='f')return L===6&&new Set(q.slice(1,5).map(x=>x.toLowerCase())).size===4;
  if(t==='t')return L===4&&q[1].includes('___')&&q[2].length<60;
  if(t==='o'){const w=q[1].split(' ');return L===4&&w.length>=4&&w.length<=16;}
  return false;
}
async function genGrammar(c,out,btn){
  if(needAI(out))return;
  const old=btn.textContent;btn.disabled=true;btn.textContent='Готовлю…';out.innerHTML='';
  const theme=THEMES[Math.floor(Math.random()*THEMES.length)];
  const prompt=`Create 8 new practice items on the English grammar topic "${c.t}" for a Russian-speaking IELTS candidate (current level B2, aim band 7-8).
Key rules of the topic: ${c.f.join(' ')}
Use ADVANCED vocabulary (B2-C1, academic and IELTS-relevant, for example about ${theme}) inside the sentences, so the learner also meets new words, but keep the grammar point itself clear and the answer unambiguous: exactly one correct option, and for typed items give every acceptable variant.
Item formats, each is a JSON array of strings:
["m", stem with ___ , correct, wrong1, wrong2, wrong3, explanation]   multiple choice, 3 plausible wrong options
["f", correct sentence, wrong1, wrong2, wrong3, explanation]   which sentence is correct; wrong ones contain one typical error each
["t", stem with ___ and the base verb in brackets if needed, accepted answers separated by | , explanation]   typed answer
["o", the correct full sentence, Russian translation of it, explanation]   word ordering
Use a mix: 3 "m", 2 "f", 2 "t", 1 "o". Explanations in Russian, 1-2 short sentences, say WHY. Never repeat the same sentence. Return ONLY a JSON array of 8 items.`;
  try{
    const r=await AI.json(prompt,{modelTier:'default',cache:false});
    const items=(Array.isArray(r)?r:(r&&r.items)||[]).filter(validItem);
    if(items.length<3)throw new Error('few');
    S.gen=S.gen||{};S.gen[c.id]=(S.gen[c.id]||0)+1;save();
    const n=S.gen[c.id];
    session(items.map((q,i)=>({c,i,q,key:'ai:'+c.id+':'+n+':'+i,h:'Новые задания от Claude · лексика B2–C1'})),c.t,{});
  }catch(e){
    out.innerHTML=`<div class="warn">${e&&e.code==='rate_limited'?'Слишком много запросов, подожди минуту.':e&&e.code==='not_granted'?'Доступ не разрешён.':'Не получилось подготовить задания, попробуй ещё раз.'}</div>`;
    btn.disabled=false;btn.textContent=old;
  }
}

// Vocabulary exercises from Claude: collocations, phrasal verbs, words in sentences, word building.
async function genLex(kind,subject,words,out,btn){
  if(needAI(out))return;
  const old=btn.textContent;btn.disabled=true;btn.textContent='Готовлю…';out.innerHTML='';
  const common=`for a Russian-speaking IELTS candidate (B2, aiming for band 7-8). Use natural, correct English, B2-C1 level. Exactly one option must be correct. Explanations in Russian, one short sentence, include the Russian translation of the target expression.
Formats, each a JSON array of strings:
["m", sentence with ___ , correct, wrong1, wrong2, wrong3, explanation]
["t", sentence with ___ , accepted answers separated by | , explanation]
Return ONLY a JSON array of 8 items: 6 "m" and 2 "t".`;
  const P={
   colloc:`Create 8 exercises on collocations connected with the topic "${subject}". The blank replaces one word of a collocation (verb, adjective or noun); wrong options must be plausible words that do NOT collocate with the rest. `+common,
   pv:`Create 8 exercises on phrasal verbs from the group "${subject}". The blank replaces the whole phrasal verb (give 4 options that are phrasal verbs or look similar), or only the particle for 2 of the items. `+common,
   words:`Create 8 exercises where the blank must be one of these target words or expressions: ${words.join('; ')}. Use each target at most once; wrong options are other words of similar form or meaning (they can come from the same list). Sentences should be about IELTS-style topics. `+common,
   wb:`Create 8 word-formation exercises like in IELTS and Cambridge tests: the sentence has a blank and the base word is given in capitals in brackets, for example "The ___ (ECONOMY) of the region grew." Type "t" only, with every accepted form; the base word must be changed to noun, adjective, adverb, verb or negative form. Topic: ${subject}. Return ONLY a JSON array of 8 "t" items. Format: ["t", sentence with ___ and (BASE), accepted answers separated by | , explanation in Russian showing the word family].`
  };
  try{
    const r=await AI.json(P[kind],{modelTier:'default',cache:false});
    const items=(Array.isArray(r)?r:(r&&r.items)||[]).filter(validItem);
    if(items.length<3)throw new Error('few');
    const c={id:'lex',t:subject};
    session(items.map((q,i)=>({c,i,q,key:'lex:'+Date.now()+':'+i,h:({colloc:'Коллокации',pv:'Фразовые глаголы',words:'Слова в предложениях',wb:'Словообразование'})[kind]+' · '+subject})),subject,{});
  }catch(e){
    out.innerHTML=`<div class="warn">${e&&e.code==='rate_limited'?'Слишком много запросов, подожди минуту.':e&&e.code==='not_granted'?'Доступ не разрешён.':'Не получилось подготовить задания, попробуй ещё раз.'}</div>`;
    btn.disabled=false;btn.textContent=old;
  }
}
